function normalizeType(t){return ['expense','income','investment'].includes(t)?t:'expense'};function listed(){return [...db.transactions].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||0)-(a.createdAt||0))};const sum=(arr,type)=>round(arr.filter(t=>t.type===type).reduce((n,t)=>n+Number(t.amount||0),0));const currentMonth=()=>today().slice(0,7);const monthTx=m=>db.transactions.filter(t=>String(t.date).slice(0,7)===m);const accountName=id=>db.accounts.find(a=>a.id===id)?.name||'未指定';const accountBalance=a=>round(Number(a.balance||0)+db.transactions.filter(t=>t.accountId===a.id&&(!a.balanceSetAt||Number(t.createdAt||0)>Number(a.balanceSetAt))).reduce((n,t)=>n+(t.type==='income'?1:-1)*Number(t.amount||0),0));const accountOptions=(selected)=>db.accounts.map(a=>`<option value="${h(a.id)}" ${a.id===selected?'selected':''}>${h(a.name)}</option>`).join('');const catOptions=(selected)=>cats.map(([c])=>`<option ${c===selected?'selected':''} value="${c}">${c}</option>`).join('');function fmtDate(s){return s?.replace(/-/g,'.')||''};function amountHTML(t){return `<span class="amount ${t.type==='income'?'positive':t.type==='investment'?'investment':'negative'}">${t.type==='income'?'+':'−'}${money(t.amount)}</span>`}
