// Fixed items are configured by their start month for recurring reporting.
// An existing weekly standing order can have been set up in the middle of its
// start month while earlier weekly deductions have already happened.
// Both posting and reporting use this same occurrence generator.
function scheduledDates(rule,endDate){
 const start=/^\d{4}-\d{2}-\d{2}$/.test(rule.start||'')?rule.start:currentMonth()+'-01';
 if(!/^\d{4}-\d{2}-\d{2}$/.test(endDate)||start.slice(0,7)>endDate.slice(0,7))return [];
 const dates=[];
 if(rule.frequency==='daily'){
  let d=dateFrom(start),counter=0;
  while(localDate(d)<=endDate&&counter++<20000){dates.push(localDate(d));d.setDate(d.getDate()+1)}
 }else if(rule.frequency==='weekly'){
  const weekday=Number(rule.weekday);
  if(!Number.isInteger(weekday)||weekday<0||weekday>6)return [];
  const d=dateFrom(start.slice(0,7)+'-01');d.setDate(d.getDate()+(weekday-d.getDay()+7)%7);
  let counter=0;
  while(localDate(d)<=endDate&&counter++<6000){dates.push(localDate(d));d.setDate(d.getDate()+7)}
 }else if(rule.frequency==='monthly'){
  let [y,m]=start.slice(0,7).split('-').map(Number),counter=0;
  while(counter++<1200){
   const d=new Date(y,m-1,1,12),month=localDate(d).slice(0,7);
   if(month>endDate.slice(0,7))break;
   const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();
   const day=Math.min(Math.max(1,Math.floor(Number(rule.day)||1)),last);
   const occurrence=month+'-'+String(day).padStart(2,'0');
   if(occurrence<=endDate)dates.push(occurrence);
   m++;
  }
 }else if(rule.frequency==='yearly'){
  const [startYear,startMonth,startDay]=start.split('-').map(Number),endYear=Number(endDate.slice(0,4));
  let counter=0;
  for(let year=startYear;year<=endYear&&counter++<200;year++){
   const last=new Date(year,startMonth,0).getDate();
   const occurrence=`${year}-${String(startMonth).padStart(2,'0')}-${String(Math.min(startDay,last)).padStart(2,'0')}`;
   if(occurrence>=start&&occurrence<=endDate)dates.push(occurrence);
  }
 }
 return dates;
}
function autoRules(){
 const end=today(),skipped=new Set(db.skippedOccurrences||[]);
 const existing=new Set(db.transactions.filter(t=>t.ruleId).map(t=>t.ruleId+'|'+t.date));
 let added=0;
 for(const r of db.rules){
  if(!r.active||!Number.isFinite(Number(r.amount))||Number(r.amount)<=0)continue;
  for(const date of scheduledDates(r,end)){
   const key=r.id+'|'+date;
   if(skipped.has(key)||existing.has(key))continue;
   db.transactions.push({id:uid(),date,type:normalizeType(r.type),amount:round(r.amount),category:r.category||'其他',note:r.name||'固定项目',accountId:r.accountId||db.accounts[0]?.id||'',ruleId:r.id,createdAt:Date.now()});
   existing.add(key);added++;
  }
 }
 if(added)save();return added;
}
