function plannedRowTx(t){return `<div class="rowitem planned-row" data-skip-planned="${h(t.ruleId)}|${h(t.date)}" role="button" tabindex="0" title="点击取消本次固定支出"><div class="avatar">${emoji(t.category)}</div><div class="rowitem-body"><div class="rowitem-title">${h(t.note||t.category)}</div><div class="rowitem-meta">${fmtDate(t.date)} · ${h(t.category)} · ${h(accountName(t.accountId))} · 固定支出（未到期）</div></div>${amountHTML(t)}<span class="action-chevron">›</span></div>`}
function monthShift(date,offset){const d=new Date(date.getFullYear(),date.getMonth()+offset,1);return localDate(d).slice(0,7)}
function scheduledFixedExpense(periodStart,periodEnd){
  let planned=0;
  const todayStr=today();
  for(const r of db.rules){
    if(!r.active||r.type!=='expense'||!(Number(r.amount)>0))continue;
    for(const day of scheduledDates(r,periodEnd)){
      if(day<periodStart)continue;
      if(!db.transactions.some(t=>t.ruleId===r.id&&t.date===day&&t.type==='expense')&&!(db.skippedOccurrences||[]).includes(r.id+'|'+day)&&day>todayStr)planned+=Number(r.amount);
    }
  }
  return round(planned);
}
function statsPage(){const p=state.period;const report=reportingTransactions();let periodList=[],label='';const now=dateFrom(today());if(p==='day'){let end=today();for(let i=6;i>=0;i--){let day=addDays(end,-i);periodList.push({key:day,label:day.slice(5),items:report.filter(t=>t.date===day)})}label='近 7 天'}else if(p==='month'){for(let i=5;i>=0;i--){let month=monthShift(now,-i);periodList.push({key:month,label:month.slice(5)+'月',items:report.filter(t=>t.date.slice(0,7)===month)})}label='近 6 个月'}else{let y=now.getFullYear();for(let i=4;i>=0;i--){let yr=String(y-i);periodList.push({key:yr,label:yr+'年',items:report.filter(t=>t.date?.startsWith(yr))})}label='近 5 年'}const tx=p==='day'?report.filter(t=>t.date===today()):p==='month'?report.filter(t=>t.date.slice(0,7)===currentMonth()):report.filter(t=>t.date?.startsWith(String(now.getFullYear())));const expense=sum(tx,'expense'),income=sum(tx,'income'),invest=sum(tx,'investment');const overMonths=new Set();for(const d of periodList){if(p==='month'&&db.budget>0&&sum(d.items,'expense')>db.budget)overMonths.add(d.key)}const periodStart=p==='day'?today():p==='month'?currentMonth()+'-01':String(now.getFullYear())+'-01-01';const periodEnd=p==='day'?today():p==='month'?currentMonth()+'-'+String(new Date(now.getFullYear(),now.getMonth()+1,0).getDate()).padStart(2,'0'):String(now.getFullYear())+'-12-31';const fixedPlanned=tx.filter(t=>t.planned&&t.type==='expense').reduce((n,t)=>n+Number(t.amount),0);const fixedActual=tx.filter(t=>t.ruleId&&!t.planned&&t.type==='expense').reduce((n,t)=>n+Number(t.amount),0);let map={};for(let t of tx.filter(t=>t.type==='expense'))map[t.category]=(map[t.category]||0)+Number(t.amount);let groups=Object.entries(map).sort((a,b)=>b[1]-a[1]);
let percents=groups.map(([,v])=>Math.floor(v/Math.max(expense,1)*1000)/10);
let tenthsLeft=Math.max(0,1000-Math.round(percents.reduce((n,v)=>n+v*10,0)));
let order=groups.map(([,v],i)=>({i,rem:v/Math.max(expense,1)*1000-Math.floor(v/Math.max(expense,1)*1000)})).sort((a,b)=>b.rem-a.rem);
for(let k=0;k<tenthsLeft;k++)percents[order[k%order.length].i]=round(percents[order[k%order.length].i]+0.1);
let deg=0;let gradient=groups.length?groups.map(([c,n],i)=>{let end=deg+n/expense*360;let segment=`${colors[i%colors.length]} ${deg}deg ${end}deg`;deg=end;return segment}).join(','):'#eeeeea 0deg 360deg';let values=periodList.map(x=>sum(x.items,'expense')),highest=Math.max(1,...values);return `<div class="page-head"><h1>看看钱去了哪里。</h1><p class="subline">分类清晰，花销一目了然。</p></div><div class="segmented" style="margin-bottom:20px">${[['day','日'],['month','月'],['year','年']].map(([v,t])=>`<button data-period="${v}" class="${p===v?'active':''}">${t}统计</button>`).join('')}</div><div class="summary-row"><div class="panel"><div class="sum-label">${p==='day'?'今天':p==='month'?'本月':'今年'}支出</div><div class="sum-value small">${money(expense)}</div><div class="caption" style="margin-top:7px">含固定消费 ${money(fixedActual+fixedPlanned)}</div></div><div class="panel"><div class="sum-label">${p==='day'?'今天':p==='month'?'本月':'今年'}收入</div><div class="sum-value small positive">${money(income)}</div></div></div><div class="section-head"><h2>消费趋势</h2><span class="caption">${label}</span></div><div class="panel"><div class="chart-bar-wrap">${periodList.map((d,i)=>`<div class="bar-cell" title="${h(d.key)}：${money(values[i])}"><div class="bar-track"><div class="bar ${overMonths.has(d.key)?'over-budget':''}" style="height:${Math.max(2,values[i]/highest*109)}px"></div></div><div class="bar-label">${h(d.label)}${overMonths.has(d.key)?'<span class="over-budget-label">超支</span>':''}</div></div>`).join('')}</div></div>${p==='month'?`<p class="caption" style="margin:10px 3px 0">标记为「超支」的月份：当月消费（含固定消费）超过当前月预算 ${money(db.budget)}。投资与借款不计入。</p>`:''}<div class="section-head"><h2>分类占比</h2><span class="caption">${groups.length} 个分类</span></div><div class="panel">${expense?`<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${gradient})"><div class="donut-center"><span class="caption">总支出</span><b style="font-size:14px;margin-top:5px">${money(expense)}</b></div></div><div class="legend">${groups.slice(0,6).map(([c,n],i)=>`<div class="legend-row"><span><i class="dot" style="background:${colors[i%colors.length]}"></i>${h(c)}</span><b>${percents[i].toFixed(1)}%</b></div>`).join('')}</div></div>`:'<div class="empty">当前时间范围还没有消费记录。</div>'}</div><div class="section-head"><h2>固定项目与借款</h2></div><div class="panel"><div class="between"><span class="caption">本期已扣款的固定消费</span><b>${money(tx.filter(t=>t.ruleId&&!t.planned&&t.type==='expense').reduce((n,t)=>n+Number(t.amount),0))}</b></div><div class="between" style="margin-top:15px"><span class="caption">本期预先计入的固定消费</span><b>${money(fixedPlanned)}</b></div><div class="between" style="margin-top:15px"><span class="caption">本期消费总额（已含固定支出）</span><b>${money(expense)}</b></div><p class="caption" style="margin-top:9px">本月固定支出提前纳入本月支出、柱状图、饼图及预算；尚未扣款的项目会在到期后自动生成正式账单，不会重复计算。</p><div class="between" style="margin-top:15px"><span class="caption">尚未收回借款（不计入消费）</span><b>${money(db.loans.reduce((n,l)=>n+loanRemaining(l),0))}</b></div></div><div class="section-head"><h2>收支结余</h2></div><div class="panel"><div class="between"><span class="caption">收入 − 消费支出</span><b class="${income-expense>=0?'positive':''}">${money(income-expense)}</b></div><div class="between" style="margin-top:15px"><span class="caption">投资流出（单独列示）</span><b class="investment">${money(invest)}</b></div><div class="between" style="margin-top:15px"><span class="caption">扣除投资后的现金净流入</span><b>${money(income-expense-invest)}</b></div></div>`}
function loanRemaining(l){return round(Math.max(0,Number(l.amount||0)-(l.repayments||[]).reduce((n,r)=>n+Number(r.amount||0),0)))}
function loanSection(){const loans=[...db.loans].sort((a,b)=>(b.date||'').localeCompare(a.date||''));const outstanding=round(loans.reduce((n,l)=>n+loanRemaining(l),0));return `<div class="panel"><div class="between"><div><div class="sum-label">尚未收回</div><div class="sum-value small">${money(outstanding)}</div></div><span class="caption">借款不算日常消费</span></div>${loans.map(l=>`<div class="rowitem"><div class="avatar">${loanRemaining(l)>0?'🤝':'✓'}</div><div class="rowitem-body"><div class="rowitem-title">${h(l.person)}</div><div class="rowitem-meta">${h(l.date)} · 借出 ${money(l.amount)} · ${loanRemaining(l)>0?'待还 '+money(loanRemaining(l)):'已全部还清'}</div></div><button class="soft-btn" data-loan="${h(l.id)}">${loanRemaining(l)>0?'已还 / 编辑':'查看'}</button></div>`).join('')||'<div class="empty">暂无借款记录。点击「记借出」开始记录。</div>'}</div>`}
function loanForm(l){const edit=!!l;l=l||{id:uid(),person:'',amount:'',date:today(),note:'',repayments:[]};openModal(edit?'借款详情':'记录借出',`<form id="loan-form"><div class="form-field"><label>借给谁</label><input name="person" required maxlength="60" value="${h(l.person)}" placeholder="姓名或称呼"></div><div class="field-grid"><div class="form-field"><label>借出金额（元）</label><input name="amount" type="number" min="0.01" step="0.01" required value="${h(l.amount)}"></div><div class="form-field"><label>借出日期</label><input name="date" type="date" required value="${h(l.date)}"></div></div><div class="form-field"><label>备注（可选）</label><input name="note" maxlength="120" value="${h(l.note||'')}"></div><button class="primary-btn full" type="submit">${edit?'保存借款信息':'确认借出'}</button></form>${edit?`<div class="section-head"><h2>还款记录</h2><span class="caption">待还 ${money(loanRemaining(l))}</span></div><div class="panel">${(l.repayments||[]).map(r=>`<div class="between" style="margin-bottom:9px"><span class="caption">${h(r.date)} · 已还 ${money(r.amount)}</span><button class="link-btn" data-delete-repay="${h(r.id)}">删除</button></div>`).join('')||'<div class="caption">还没有还款记录</div>'}</div>${loanRemaining(l)>0?`<form id="repay-form"><div class="field-grid"><div class="form-field"><label>本次已还（元）</label><input type="number" name="amount" min="0.01" max="${loanRemaining(l)}" step="0.01" required value="${loanRemaining(l)}"></div><div class="form-field"><label>还款日期</label><input type="date" name="date" required value="${today()}"></div></div><button class="primary-btn full" type="submit">记录已还</button></form>`:''}<button class="danger-btn full" type="button" id="delete-loan" style="margin-top:13px">删除这笔借款</button>`:''}`);const form=root.querySelector('#loan-form');form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);const amount=round(f.get('amount'));const paid=round((l.repayments||[]).reduce((n,r)=>n+Number(r.amount),0));if(!Number.isFinite(amount)||amount<=0||amount>1e10||amount<paid){toast('借出金额必须不少于已还金额');return}const v={...l,person:String(f.get('person')).trim(),amount,date:String(f.get('date')),note:String(f.get('note')).trim()};if(!v.person)return;if(edit)db.loans[db.loans.findIndex(x=>x.id===l.id)]=v;else db.loans.push(v);save();closeModal();render();toast('借款已保存')};if(!edit)return;const repay=root.querySelector('#repay-form');if(repay)repay.onsubmit=e=>{e.preventDefault();const f=new FormData(repay),amount=round(f.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>loanRemaining(l)){toast('还款金额不能超过待还金额');return}l.repayments=l.repayments||[];l.repayments.push({id:uid(),date:String(f.get('date')),amount});save();closeModal();render();toast('已记录还款')};root.querySelectorAll('[data-delete-repay]').forEach(b=>b.onclick=()=>{if(!confirm('删除这笔还款记录？'))return;l.repayments=l.repayments.filter(r=>r.id!==b.dataset.deleteRepay);save();closeModal();render();loanForm(l)});root.querySelector('#delete-loan').onclick=()=>{if(!confirm('确定删除整笔借款和还款记录？'))return;db.loans=db.loans.filter(x=>x.id!==l.id);save();closeModal();render()}}
// The fixed-page numbers are calendar sums, not a 52/12 monthly average.
// Posted occurrences take precedence over generated ones. Paused rules keep
// their already-posted history; skipped occurrences are never reintroduced.
function fixedFlowForMonth(month){
 const last=month+'-'+String(new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate()).padStart(2,'0');
 const cutoff=today()<last?today():last;
 const rows=[];
 const existing=new Set();
 for(const t of db.transactions){
  if(!t.ruleId||String(t.date).slice(0,7)!==month||!['expense','investment'].includes(t.type))continue;
  const key=t.ruleId+'|'+t.date;
  if(existing.has(key))continue;
  existing.add(key);rows.push(t);
 }
 const skipped=new Set(db.skippedOccurrences||[]);
 for(const r of db.rules){
  if(!r.active||!['expense','investment'].includes(r.type)||!(Number(r.amount)>0))continue;
  for(const date of scheduledDates(r,last)){
   if(!date.startsWith(month))continue;
   const key=r.id+'|'+date;
   if(existing.has(key)||skipped.has(key))continue;
   rows.push({ruleId:r.id,date,amount:round(r.amount),type:r.type,planned:true});
   existing.add(key);
  }
 }
 return {
  toDate:round(rows.filter(t=>t.date<=cutoff).reduce((n,t)=>n+Number(t.amount||0),0)),
  monthTotal:round(rows.reduce((n,t)=>n+Number(t.amount||0),0)),
  occurred:rows.filter(t=>t.date<=cutoff).length,
  scheduled:rows.length
 };
}
function frequencyText(r){if(r.frequency==='daily')return '每日';if(r.frequency==='weekly')return `每周${'日一二三四五六'[Number(r.weekday)]}`;if(r.frequency==='yearly')return `每年${String(r.start||'').slice(5).replace('-','月')}日`;return `每月${r.day}日`};function rulesPage(){let active=db.rules.filter(r=>r.active);const fixed=fixedFlowForMonth(currentMonth());return `<div class="page-head"><h1>固定的小事，自动记。</h1><p class="subline">每次打开 App，自动补录到期项目。</p></div><div class="panel"><div class="sum-label">本月截至今天的固定流出（含投资）</div><div class="sum-value">${money(fixed.toDate)}</div><p class="caption">按实际日历中的扣款日计算，已包含本月到期的 ${fixed.occurred} 笔；不再使用全年52周平均估算。</p><div class="between" style="margin-top:13px;border-top:1px solid var(--line);padding-top:13px"><span class="caption">本月整月计划流出（含未到期）</span><b style="font-size:14px">${money(fixed.monthTotal)}</b></div></div><div class="section-head"><h2>借出与已还</h2><button class="link-btn" data-action="loan-add">+ 记借出</button></div>${loanSection()}<div class="section-head"><h2>循环项目</h2><div style="display:flex;align-items:center;gap:10px"><span class="caption">${active.length} 项开启</span><button class="link-btn" data-action="rule">+ 记固定</button></div></div>${db.rules.map(r=>`<div class="panel rule-panel"><div class="between"><div class="between" style="gap:12px"><div class="avatar">${emoji(r.category)}</div><div><div style="font-size:13px;font-weight:600">${h(r.name)}</div><div class="caption" style="margin-top:5px">${frequencyText(r)}</div></div></div><input class="switch" type="checkbox" data-toggle-rule="${h(r.id)}" ${r.active?'checked':''} aria-label="切换${h(r.name)}"></div><div class="between" style="margin-top:18px"><div><b>${money(r.amount)}</b> <span class="pill">${r.type==='investment'?'投资':r.type==='income'?'收入':'消费'}</span></div><button class="link-btn" data-edit-rule="${h(r.id)}">编辑 →</button></div></div>`).join('')||'<div class="empty">还没有循环项目。</div>'}<div class="small-note" style="margin-top:17px">自动记录只是账本记录，不会向支付宝、银行或基金发起真实扣款。设置了开始日期后，到期会在打开 App 时补录；请定期核对实际交易。</div>`}
function settingsPage(){return `<div class="page-head"><h1>只留下需要的。</h1><p class="subline">你的账本数据默认只保存在这台设备。</p></div><div class="section-head"><h2>图标主题</h2></div><div class="panel"><div class="theme-grid"><button class="theme-choice ${db.theme==='plain'?'active':''}" data-theme="plain" aria-pressed="${db.theme==='plain'}"><span class="theme-plain-preview"><i style="--icon-x:0;--icon-y:0"></i><i style="--icon-x:1;--icon-y:0"></i><i style="--icon-x:2;--icon-y:0"></i></span><b>质感生活版</b><small>柔和立体生活物件</small></button><button class="theme-choice ${db.theme==='cat'?'active':''}" data-theme="cat" aria-pressed="${db.theme==='cat'}"><span class="theme-cat-preview"><i style="--icon-x:0;--icon-y:0"></i><i style="--icon-x:1;--icon-y:0"></i><i style="--icon-x:2;--icon-y:0"></i></span><b>小猫版</b><small>原创白色小猫主题</small></button></div><p class="caption theme-caption">切换后会立即应用到首页、账单、统计和固定项目。</p></div><div class="section-head"><h2>预算</h2></div><div class="panel between"><div><div class="sum-label">每月消费预算</div><div style="font-size:19px;font-weight:600;margin-top:8px">${money(db.budget)}</div></div><button class="soft-btn" data-action="budget">修改</button></div><div class="section-head"><h2>数据备份与迁移</h2></div><div class="panel action-list"><div class="rowitem" data-action="export-json"><div class="avatar">📦</div><div class="rowitem-body"><div class="rowitem-title">导出完整备份（JSON）</div><div class="rowitem-meta">账单、预算、固定项目、借出与还款全部保留</div></div><span class="action-chevron">›</span></div><div class="rowitem" data-action="import"><div class="avatar">📥</div><div class="rowitem-body"><div class="rowitem-title">导入完整备份</div><div class="rowitem-meta">换手机时恢复所有数据</div></div><span class="action-chevron">›</span></div><div class="rowitem" data-action="export-csv"><div class="avatar">📄</div><div class="rowitem-body"><div class="rowitem-title">导出 CSV 表格</div><div class="rowitem-meta">可用 Excel / Numbers 查看</div></div><span class="action-chevron">›</span></div></div><div class="section-head"><h2>隐私与使用</h2></div><div class="panel"><div style="font-size:12px;line-height:2;color:#74766c">✓ 免费，无广告，无需注册<br>✓ 记账数据保存在浏览器本地<br>✓ 语音功能取决于浏览器及其语音服务<br>✓ 可添加到 iPhone 主屏幕<br>✓ 定期导出 JSON 备份，避免清除浏览器数据后丢失</div><button class="danger-btn" style="margin-top:16px" data-action="clear">清空全部数据</button></div>`}
function statsScope(){const report=reportingTransactions(),now=dateFrom(today()),p=state.period;let periodList=[];if(p==='day'){for(let i=6;i>=0;i--){const key=addDays(today(),-i);periodList.push({key,label:key.slice(5),items:report.filter(t=>t.date===key)})}}else if(p==='month'){for(let i=5;i>=0;i--){const key=monthShift(now,-i);periodList.push({key,label:key.slice(5)+'月',items:report.filter(t=>t.date.slice(0,7)===key)})}}else{const y=now.getFullYear();for(let i=4;i>=0;i--){const key=String(y-i);periodList.push({key,label:key+'年',items:report.filter(t=>t.date?.startsWith(key))})}}const tx=p==='day'?report.filter(t=>t.date===today()):p==='month'?report.filter(t=>t.date.slice(0,7)===currentMonth()):report.filter(t=>t.date?.startsWith(String(now.getFullYear())));return{p,periodList,tx}}
function trendLinePanel(){const {periodList}=statsScope(),values=periodList.map(x=>sum(x.items,'expense')),max=Math.max(1,...values),width=320,height=132,pad=22,step=(width-pad*2)/Math.max(1,values.length-1),points=values.map((v,i)=>`${pad+i*step},${height-27-v/max*(height-52)}`),area=`${pad},${height-27} ${points.join(' ')} ${pad+(values.length-1)*step},${height-27}`;return `<div class="panel trend-line-panel"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="消费趋势折线图"><path class="trend-grid" d="M${pad} 25H${width-pad}M${pad} 65H${width-pad}M${pad} ${height-27}H${width-pad}"/><polygon class="trend-area" points="${area}"/><polyline class="trend-line" points="${points.join(' ')}"/>${points.map((pt,i)=>{const [x,y]=pt.split(',');return `<circle class="trend-dot" cx="${x}" cy="${y}" r="2.35"><title>${periodList[i].key}：${money(values[i])}</title></circle>`}).join('')}${periodList.map((d,i)=>`<text x="${pad+i*step}" y="${height-7}" text-anchor="middle">${h(d.label)}</text>`).join('')}</svg></div>`}
function categoryShareSection(){const {tx}=statsScope(),expense=sum(tx,'expense'),map={};for(const t of tx.filter(t=>t.type==='expense')){const name=t.ruleId?'固定支出':t.category||'其他';map[name]=(map[name]||0)+Number(t.amount)}const groups=Object.entries(map).sort((a,b)=>b[1]-a[1]),total=Math.max(expense,1);let deg=0;const gradient=groups.length?groups.map(([,n],i)=>{const end=deg+n/total*360,s=`${colors[i%colors.length]} ${deg}deg ${end}deg`;deg=end;return s}).join(','):'#eeeeea 0deg 360deg';return `<div class="section-head"><h2>分类占比</h2><span class="caption">${groups.length} 个分类</span></div><div class="panel category-share-panel">${expense?`<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${gradient})"><div class="donut-center"><span class="caption">总支出</span><b style="font-size:14px;margin-top:5px">${money(expense)}</b></div></div><div class="legend">${groups.slice(0,8).map(([c,n],i)=>`<div class="legend-row"><span><i class="dot" style="background:${colors[i%colors.length]}"></i>${h(c)}</span><button class="legend-value" data-category-display="${categoryDisplay==='percent'?'amount':'percent'}" title="点击切换百分比和金额">${categoryDisplay==='percent'?(n/expense*100).toFixed(1)+'%':money(n)}</button></div>`).join('')}</div></div>`:'<div class="empty">当前时间范围还没有消费记录。</div>'}</div>`}
const statsPageBase=statsPage;statsPage=()=>{let html=statsPageBase();const periodControl=`<label class="stats-period-control"><span>统计周期</span><select id="stats-period-select"><option value="day" ${state.period==='day'?'selected':''}>近 7 天</option><option value="month" ${state.period==='month'?'selected':''}>按月</option><option value="year" ${state.period==='year'?'selected':''}>按年</option></select></label>`;html=html.replace(/<div class="segmented" style="margin-bottom:20px">[\s\S]*?<\/div>/,'');html=html.replace(/(<div class="section-head"><h2>消费趋势<\/h2><span class="caption">[\s\S]*?<\/span><\/div>)/,`$1${periodControl}`);html=html.replace(/<div class="panel"><div class="chart-bar-wrap">[\s\S]*?<\/div><\/div>(?=<p class="caption"|<div class="section-head"><h2>分类占比)/,trendLinePanel());html=html.replace(/<div class="section-head"><h2>分类占比[\s\S]*?(?=<div class="section-head"><h2>固定项目与借款)/,categoryShareSection());return html};
const ledgerPageBase=ledgerPage;ledgerPage=()=>ledgerPageBase().replace(/<div class="month-control"><button data-month="-1">‹<\/button><b>.*?<\/b><button data-month="1">›<\/button><\/div>/,`<div class="month-control month-picker-control"><button data-month="-1" aria-label="上个月">‹</button><label><span class="sr-only">选择月份</span><input id="ledger-month-picker" type="month" value="${state.focus}" aria-label="选择账单月份"></label><button data-month="1" aria-label="下个月">›</button></div>`);
