const renderBase=render;render=()=>{document.documentElement.dataset.background=db.background||'warm';renderBase();const composer=app.querySelector('#composer'),speechInput=app.querySelector('#speech-input');if(speechInput){speechInput.disabled=false;speechInput.readOnly=false;speechInput.tabIndex=0;speechInput.onclick=()=>speechInput.focus();speechInput.ontouchend=()=>speechInput.focus()}if(composer)composer.onsubmit=e=>{e.preventDefault();e.stopPropagation();preview(speechInput?.value||'')};const period=app.querySelector('#stats-period-select');if(period){period.disabled=false;period.onchange=e=>{e.stopPropagation();state.period=period.value;render()}}};
const settingsPageThemes=settingsPage;settingsPage=()=>settingsPageThemes();
function openModal(title,body){root.innerHTML=`<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="modal-head"><h2>${h(title)}</h2><button class="modal-x" data-close aria-label="关闭">×</button></div>${body}</section></div>`;root.querySelector('.modal-shade').addEventListener('click',e=>{if(e.target.classList.contains('modal-shade'))closeModal()})}function closeModal(){root.innerHTML=''}
function txForm(t){const edit=!!t;t=t||{id:uid(),date:today(),type:'expense',amount:'',category:'餐饮',note:'',accountId:db.accounts[0]?.id};openModal(edit?'编辑账单':'手动添加账单',`<form id="tx-form"><div class="form-field"><label>收支类型</label><select name="type"><option value="expense" ${t.type==='expense'?'selected':''}>消费支出</option><option value="income" ${t.type==='income'?'selected':''}>收入</option><option value="investment" ${t.type==='investment'?'selected':''}>投资流出（不算消费）</option></select></div><div class="field-grid"><div class="form-field"><label>金额（元）</label><input name="amount" type="number" min="0.01" step="0.01" required value="${h(t.amount)}"></div><div class="form-field"><label>日期</label><input name="date" type="date" required value="${h(t.date)}"></div></div><div class="form-field"><label>备注</label><input name="note" maxlength="80" placeholder="如：午饭、猫粮" value="${h(t.note)}"></div><div class="field-grid"><div class="form-field"><label>分类</label><select name="category">${catOptions(t.category)}</select></div></div><button class="primary-btn full" style="margin-top:10px" type="submit">${edit?'保存修改':'保存账单'}</button>${edit?'<button class="danger-btn full" style="margin-top:10px" type="button" id="delete-tx">删除账单</button>':''}</form>`);root.querySelector('#tx-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={id:t.id,date:String(f.get('date')),type:normalizeType(f.get('type')),amount:round(f.get('amount')),category:String(f.get('category')),note:String(f.get('note')).trim(),accountId:t.accountId||db.accounts[0]?.id||'',createdAt:t.createdAt||Date.now()};if(!(v.amount>0)||!/^\d{4}-\d\d-\d\d$/.test(v.date)){toast('请输入有效的金额和日期');return}if(edit){const idx=db.transactions.findIndex(x=>x.id===t.id);if(idx<0)return;
 if(t.ruleId&&v.date!==t.date){
  db.skippedOccurrences=db.skippedOccurrences||[];
  const oldKey=t.ruleId+'|'+t.date;if(!db.skippedOccurrences.includes(oldKey))db.skippedOccurrences.push(oldKey);
  db.transactions[idx]={...t,...v,ruleId:undefined};
 }else db.transactions[idx]={...t,...v};
 }else db.transactions.push(v);save();closeModal();render();toast('账单已保存')};if(edit)root.querySelector('#delete-tx').onclick=()=>{if(!confirm('确定删除这笔账单吗？'))return;if(t.ruleId){db.skippedOccurrences=db.skippedOccurrences||[];db.skippedOccurrences.push(t.ruleId+'|'+t.date)}db.transactions=db.transactions.filter(x=>x.id!==t.id);save();closeModal();render();toast('已删除账单')}}
function guessCat(s){const rules=[['美发',/染发|染头发|理发|剪头发|烫发|发型|洗剪吹/],['买菜',/买菜|菜市场|蔬菜|肉菜|生鲜|买肉|买水果/],['超市',/逛超市|超市|便利店|杂货店/],['美妆',/化妆品|口红|粉底|护肤|面膜|美甲|美容/],['服饰',/买衣|衣服|服装|鞋|包包|帽子|裤子|裙子/],['教育',/学费|书本|课程|培训|补习|学习|文具/],['通讯',/话费|流量|手机费|电话费|宽带充值/],['外出就餐',/餐厅|饭店|堂食|出去吃|下馆子/],['餐饮',/早餐|午餐|晚餐|饭|面|外卖|烧烤|火锅|麻辣|饺子|汉堡|米粉|食堂|吃/],['饮品',/咖啡|奶茶|饮料|果汁|美式|拿铁|茶饮/],['交通',/地铁|公交|打车|滴滴|出租|高铁|火车|停车|加油|车费|交通/],['购物',/购物|淘宝|拼多多|京东/],['居住',/房租|租金|物业|房贷|水费|电费|燃气|宽带/],['宠物',/猫|狗|宠物|猫粮|猫砂/],['健康',/药|医院|挂号|体检|看病|牙科/],['保险',/保险/],['还款',/分期|还款|信用卡/],['投资',/基金|定投|理财|股票|投资/],['旅行',/旅游|酒店|机票|民宿/],['娱乐',/电影|游戏|娱乐|游乐场|门票|剧本|唱歌|KTV|聚会/],['日用',/纸巾|洗衣液|牙膏|洗发|日用品/],['工资',/工资|薪水|薪资/],['兼职',/兼职|接单|稿费|项目款/],['红包',/红包|转入|收款/]];return rules.find(([,r])=>r.test(s))?.[0]||'其他'}
function parseNatural(text){text=text.trim();if(!text)return[];let date=today();if(/昨天/.test(text))date=addDays(today(),-1);if(/前天/.test(text))date=addDays(today(),-2);const explicit=text.match(/(\d{1,2})月(\d{1,2})[日号]?/);if(explicit){let year=new Date().getFullYear();date=`${year}-${explicit[1].padStart(2,'0')}-${explicit[2].padStart(2,'0')}`};let pieces=text.split(/[，,；;、\n]+|(?:\s+然后\s*|又花了)/).map(x=>x.trim()).filter(Boolean);let result=[];for(let piece of pieces){const matches=[...piece.matchAll(/(?:¥|￥)?\s*(\d+(?:\.\d{1,2})?)\s*(?:元|块钱|块|人民币)?/g)].filter(m=>{let left=piece.slice(Math.max(0,m.index-2),m.index);return !/[年月份日号\d]/.test(left.slice(-1))});if(!matches.length)continue;let m=matches[matches.length-1],amount=Number(m[1]);if(!(amount>0&&amount<1e9))continue;let note=piece.slice(0,m.index).replace(/^(今天|昨天|前天|我|花了|花|买了|买|支付了|支付|收到了|收到|收入|支出|转入|转出|中午|早上|晚上|下午|上午|的|用支付宝|用微信|银行卡|支付宝|微信)+/g,'').trim();note=note.replace(/\d{1,2}月\d{1,2}[日号]?/g,'').trim()||piece.replace(m[0],'').trim()||'日常消费';let cat=guessCat(piece);let type=/工资|薪水|薪资|收入|收到|报销到账|进账|兼职收入|红包收入/.test(piece)?'income':cat==='投资'?'investment':'expense';let accountId=db.accounts.find(a=>piece.includes(a.name))?.id||db.accounts[0]?.id||'';result.push({id:uid(),date,type,amount:round(amount),category:cat,note:note.slice(0,80),accountId,createdAt:Date.now()})}return result.slice(0,20)}
function quickTagForm(index){const tag=db.quickTags[index];if(!tag)return;openModal('修改快捷记账',`<form id="quick-tag-form"><div class="form-field"><label>按钮名称</label><input name="label" maxlength="12" required value="${h(tag.label)}" placeholder="如：记午饭"></div><div class="form-field"><label>快捷记账内容（可直接修改金额）</label><input name="text" maxlength="80" required value="${h(tag.text)}" placeholder="如：午饭28元"></div><button class="primary-btn full" type="submit">保存快捷按钮</button><button class="soft-btn full" type="button" id="use-quick-tag" style="margin-top:10px">填入首页输入框</button></form>`);const form=root.querySelector('#quick-tag-form');form.onsubmit=e=>{e.preventDefault();const label=form.elements.label.value.trim(),text=form.elements.text.value.trim();if(!label||!text){toast('请填写按钮名称和记账内容');return}db.quickTags[index]={label,text};save();closeModal();render();toast('快捷按钮已更新')};form.querySelector('#use-quick-tag').onclick=()=>{const text=form.elements.text.value.trim();closeModal();const input=document.querySelector('#speech-input');if(input){input.value=text;input.focus()}}}
function preview(text){const items=parseNatural(text);if(!items.length){toast('暂时没识别出金额，试试「午饭28元，地铁4元」');return}const suggestedAccount=items[0].accountId||db.accounts[0]?.id||'';openModal('确认识别结果',`<p class="caption" style="margin-top:-7px">识别出 ${items.length} 笔，可修改金额、分类和扣款账户，确认后才会入账。</p><form id="preview-form">${items.map((t,i)=>`<div class="preview-row"><span>${h(t.note)}</span><select data-cat="${i}">${catOptions(t.category)}</select><input data-amt="${i}" type="number" min="0.01" step="0.01" required value="${t.amount}"></div>`).join('')}<div class="form-field"><label>统一记账日期</label><input type="date" name="date" value="${items[0].date}" required></div><div class="form-field"><label>扣款 / 收款账户</label><select name="accountId" required>${accountOptions(suggestedAccount)}</select></div><button class="primary-btn full" type="submit" style="margin-top:8px">确认入账 · ${items.length} 笔</button></form>`);root.querySelector('#preview-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;const date=f.elements.date.value;const accountId=String(f.elements.accountId.value);for(let i=0;i<items.length;i++){items[i].category=f.querySelector(`[data-cat="${i}"]`).value;items[i].type=items[i].category==='投资'?'investment':items[i].type;items[i].amount=round(f.querySelector(`[data-amt="${i}"]`).value);items[i].date=date;items[i].accountId=accountId;if(!(items[i].amount>0)){toast('金额必须大于 0');return}}db.transactions.push(...items);save();closeModal();render();toast(`成功记下 ${items.length} 笔账单`)}}
function ruleForm(r){const edit=!!r;r=r||{id:uid(),name:'',amount:'',frequency:'monthly',day:20,weekday:1,start:today(),category:'其他',type:'expense',accountId:db.accounts[0]?.id,active:true};openModal(edit?'编辑固定项目':'新增固定项目',`<form id="rule-form"><div class="form-field"><label>项目名称</label><input name="name" required maxlength="50" value="${h(r.name)}" placeholder="如：每月房租"></div><div class="field-grid"><div class="form-field"><label>金额（元）</label><input type="number" name="amount" required min="0.01" step="0.01" value="${h(r.amount)}"></div><div class="form-field"><label>类型</label><select name="type"><option value="expense" ${r.type==='expense'?'selected':''}>消费</option><option value="investment" ${r.type==='investment'?'selected':''}>投资流出</option><option value="income" ${r.type==='income'?'selected':''}>收入</option></select></div></div><div class="field-grid"><div class="form-field"><label>重复方式</label><select name="frequency" id="frequency"><option value="daily" ${r.frequency==='daily'?'selected':''}>每日</option><option value="weekly" ${r.frequency==='weekly'?'selected':''}>每周</option><option value="monthly" ${r.frequency==='monthly'?'selected':''}>每月</option><option value="yearly" ${r.frequency==='yearly'?'selected':''}>每年</option></select></div><div class="form-field" id="rule-day-wrap"></div></div><div class="field-grid rule-start-category-grid"><div class="form-field"><label>开始日期</label><input type="date" name="start" required value="${h(r.start||today())}"></div><div class="form-field"><label>分类</label><select name="category">${catOptions(r.category)}</select></div></div><button class="primary-btn full" type="submit">保存固定项目</button>${edit?'<button type="button" class="danger-btn full" id="delete-rule" style="margin-top:10px">删除此项目</button>':''}</form>`);const form=root.querySelector('#rule-form');function updateFreq(){const frequency=form.elements.frequency.value;form.querySelector('#rule-day-wrap').innerHTML=frequency==='weekly'?`<label>每周哪天</label><select name="weekday">${['周日','周一','周二','周三','周四','周五','周六'].map((n,i)=>`<option value="${i}" ${Number(r.weekday)===i?'selected':''}>${n}</option>`).join('')}</select>`:frequency==='monthly'?`<label>每月几号</label><input type="number" name="day" min="1" max="31" value="${h(r.day)}" required>`:frequency==='yearly'?`<label>每年日期</label><input type="text" value="按开始日期重复" disabled>`:`<label>重复周期</label><input type="text" value="每天" disabled>`;form.querySelector('#rule-day-wrap select,#rule-day-wrap input').style.width='100%'}form.querySelector('#frequency').onchange=updateFreq;updateFreq();form.onsubmit=e=>{e.preventDefault();let f=new FormData(form),v={id:r.id,name:String(f.get('name')).trim(),amount:round(f.get('amount')),frequency:String(f.get('frequency')),day:Number(f.get('day')||1),weekday:Number(f.get('weekday')||0),start:String(f.get('start')),category:String(f.get('category')),type:normalizeType(f.get('type')),accountId:r.accountId||db.accounts[0]?.id||'',active:r.active};if(!v.name||!(v.amount>0)||v.amount>1e9){toast('请填写正确的名称和金额');return}if(edit){const idx=db.rules.findIndex(x=>x.id===r.id);db.rules[idx]=v}else db.rules.push(v);save();closeModal();render();toast('固定项目已保存')};if(edit)form.querySelector('#delete-rule').onclick=()=>{if(!confirm('删除固定项目？已生成的历史账单仍会保留。'))return;db.rules=db.rules.filter(x=>x.id!==r.id);save();closeModal();render()}}
function budgetForm(){openModal('设置每月预算',`<form id="budget-form"><div class="form-field"><label>预算金额（元）</label><input name="budget" type="number" min="0" step="0.01" required value="${h(db.budget)}"></div><p class="caption">只统计「消费支出」，不将基金定投视为生活消费。</p><button class="primary-btn full" type="submit">保存预算</button></form>`);root.querySelector('#budget-form').onsubmit=e=>{e.preventDefault();db.budget=round(e.target.elements.budget.value);if(db.budget<0)return;save();closeModal();render();toast('预算已更新')}}
function accountForm(a){const edit=!!a;a=a||{id:uid(),name:'',balance:0};openModal(edit?'修改账户':'新增账户',`<form id="account-form"><div class="form-field"><label>账户名称</label><input name="name" maxlength="30" value="${h(a.name)}" required placeholder="如：招商银行"></div><div class="form-field"><label>初始余额（元）</label><input name="balance" type="number" step="0.01" value="${h(a.balance)}" required></div><div class="small-note" style="margin:12px 0">账面余额 = 初始余额 + 已记收入 − 已记消费 − 投资流出。不会自动连接银行。</div><button class="primary-btn full" type="submit">保存账户</button>${edit?'<button class="danger-btn full" type="button" id="delete-account" style="margin-top:10px">删除账户</button>':''}</form>`);const form=root.querySelector('#account-form');form.onsubmit=e=>{e.preventDefault();let name=form.elements.name.value.trim(),balance=round(form.elements.balance.value);if(!name||!Number.isFinite(balance)){toast('请检查账户信息');return}if(edit){let idx=db.accounts.findIndex(x=>x.id===a.id);db.accounts[idx]={...a,name,balance}}else db.accounts.push({id:a.id,name,balance});save();closeModal();render();toast('账户已保存')};if(edit)form.querySelector('#delete-account').onclick=()=>{if(db.accounts.length<=1){toast('请至少保留一个账户');return}if(db.transactions.some(t=>t.accountId===a.id)||db.rules.some(r=>r.accountId===a.id)){toast('该账户已被账单或固定项目使用，请先调整关联记录');return}if(!confirm('确定删除该账户？'))return;db.accounts=db.accounts.filter(x=>x.id!==a.id);save();closeModal();render()}}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500)}function exportJSON(){download(`柠檬账本-完整备份-${today()}.json`,JSON.stringify({...db,exportedAt:new Date().toISOString(),app:'lemon-ledger'},null,2),'application/json');toast('完整备份已导出，请保存到「文件」或 iCloud 云盘')}function exportCSV(){const rows=[['日期','类型','分类','备注','金额','账户','自动规则'],...listed().map(t=>[t.date,({'expense':'支出','income':'收入','investment':'投资'})[t.type],t.category,t.note,t.amount,accountName(t.accountId),t.ruleId?'是':'否'])];let csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download(`柠檬账本-账单-${today()}.csv`,csv,'text/csv;charset=utf-8');toast('CSV 已导出')}function validBackup(x){if(!x||!Array.isArray(x.transactions)||!Array.isArray(x.accounts)||!Array.isArray(x.rules)||typeof x.budget!=='number'||(x.loans!==undefined&&!Array.isArray(x.loans))||x.accounts.length<1||x.transactions.length>200000||x.rules.length>10000)return false;return x.transactions.every(t=>typeof t.id==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(t.date)&&Number.isFinite(Number(t.amount))&&Number(t.amount)>=0&&Number(t.amount)<1e12&&['expense','income','investment'].includes(t.type))&&x.rules.every(r=>typeof r.id==='string'&&['daily','weekly','monthly','yearly'].includes(r.frequency)&&Number.isFinite(Number(r.amount))&&Number(r.amount)>=0)&&x.accounts.every(a=>typeof a.id==='string'&&typeof a.name==='string'&&Number.isFinite(Number(a.balance)))}document.querySelector('#import-file').onchange=async e=>{let file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>30*1024*1024)throw Error('备份文件过大');let x=JSON.parse(await file.text());if(!validBackup(x))throw Error('文件不是有效的柠檬账本备份');if(!confirm(`将用备份中的 ${x.transactions.length} 条账单替换当前全部数据。请先导出当前数据，再继续。确定恢复吗？`))return;db={version:2,transactions:x.transactions,accounts:x.accounts,rules:x.rules,budget:x.budget,loans:Array.isArray(x.loans)?x.loans:[],skippedOccurrences:Array.isArray(x.skippedOccurrences)?x.skippedOccurrences:[],quickTags:Array.isArray(x.quickTags)&&x.quickTags.length===3?x.quickTags:defaultQuickTags()};if(!db.accounts.some(a=>a.name==='花呗'))db.accounts.push({id:db.accounts.some(a=>a.id==='a5')?'a-huabei':'a5',name:'花呗',balance:0});save();render();toast('备份导入成功')}catch(err){toast('导入失败：'+err.message)}};
let recognizing=false,recognition=null;function speech(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){const input=document.querySelector('#speech-input');input?.focus();toast('当前浏览器无法直接语音识别：可点击键盘上的麦克风进行语音输入');return}if(recognizing&&recognition){recognition.stop();return}try{recognition=new Speech();recognition.lang='zh-CN';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{recognizing=true;const b=document.querySelector('#voice-btn');if(b){b.style.background='#e6dec8';b.title='正在聆听，点击结束'}};recognition.onresult=e=>{const input=document.querySelector('#speech-input');if(input)input.value=(input.value?input.value+'，':'')+e.results[0][0].transcript};recognition.onerror=e=>toast(e.error==='not-allowed'?'请允许浏览器使用麦克风；如仍失败，请用手机键盘语音输入':e.error==='network'?'语音服务暂时不可用，请用手机键盘语音输入':'语音识别失败，请尝试文字输入');recognition.onend=()=>{recognizing=false;const b=document.querySelector('#voice-btn');if(b){b.style.background='';b.title='语音输入'}};recognition.start()}catch{toast('语音识别启动失败')}}
let swipeSuppressClick=false;
function removeSwipedTransaction(id){
 const t=db.transactions.find(x=>x.id===id);if(!t)return;
 if(!confirm(`删除「${t.note||t.category}」${money(t.amount)}？删除后无法撤销。`))return;
 if(t.ruleId){db.skippedOccurrences=db.skippedOccurrences||[];const k=t.ruleId+'|'+t.date;if(!db.skippedOccurrences.includes(k))db.skippedOccurrences.push(k)}
 db.transactions=db.transactions.filter(x=>x.id!==id);save();render();toast('账单已删除');
}
app.addEventListener('click',e=>{
 const del=e.target.closest('[data-swipe-delete]');
 if(del){e.preventDefault();removeSwipedTransaction(del.dataset.swipeDelete);return}
 if(swipeSuppressClick&&e.target.closest('[data-open-tx]')){e.preventDefault();e.stopImmediatePropagation();swipeSuppressClick=false;return}
 const open=e.target.closest('.swipe-item.is-open .swipe-foreground');
 if(open){e.preventDefault();e.stopImmediatePropagation();open.parentElement.classList.remove('is-open')}
},true);
