const txFormAccountBase=txForm;txForm=t=>{const before=new Set(db.transactions.map(x=>x.id)),selected=t?.accountId||db.accounts[0]?.id||'';txFormAccountBase(t);const form=root.querySelector('#tx-form');if(!form)return;addAccountPicker(form,selected);form.addEventListener('submit',()=>{const accountId=form.elements.selectedAccountId?.value;if(!accountId)return;setTimeout(()=>{const saved=t?db.transactions.find(x=>x.id===t.id):[...db.transactions].reverse().find(x=>!before.has(x.id));if(saved){saved.accountId=accountId;save();render()}},0)})};
const ruleFormAccountBase=ruleForm;ruleForm=r=>{const before=new Set(db.rules.map(x=>x.id)),selected=r?.accountId||db.accounts[0]?.id||'';ruleFormAccountBase(r);const form=root.querySelector('#rule-form');if(!form)return;addAccountPicker(form,selected,'固定项目使用账户');form.addEventListener('submit',()=>{const accountId=form.elements.selectedAccountId?.value;if(!accountId)return;setTimeout(()=>{const saved=r?db.rules.find(x=>x.id===r.id):[...db.rules].reverse().find(x=>!before.has(x.id));if(saved){saved.accountId=accountId;save();render()}},0)})};
let swipeStart=null;
app.addEventListener('touchstart',e=>{
 const el=e.target.closest('.swipe-item');if(!el||e.touches.length!==1)return;
 const t=e.touches[0];swipeStart={el,x:t.clientX,y:t.clientY,moved:false};
},{passive:true});
app.addEventListener('touchmove',e=>{
 if(!swipeStart)return;const t=e.touches[0];if(!t)return;
 if(Math.abs(t.clientX-swipeStart.x)>18&&Math.abs(t.clientX-swipeStart.x)>Math.abs(t.clientY-swipeStart.y)*1.2)swipeStart.moved=true;
},{passive:true});
app.addEventListener('touchend',e=>{
 if(!swipeStart)return;const {el,x,y,moved}=swipeStart;swipeStart=null;
 const t=e.changedTouches[0];if(!t)return;
 const dx=t.clientX-x,dy=t.clientY-y;
 if(moved&&Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2){
  app.querySelectorAll('.swipe-item.is-open').forEach(n=>{if(n!==el)n.classList.remove('is-open')});
  el.classList.toggle('is-open',dx<0);if(dx>0)el.classList.remove('is-open');
  swipeSuppressClick=true;setTimeout(()=>{swipeSuppressClick=false},450);
 }
},{passive:true});
